"use client";
import type { ButtonHTMLAttributes } from "react";
import "./lens-button.css";

/** Dark glass with a spotlight edge and a soft refraction that follow the pointer.
 * On leave the light fades where it was, instead of jumping back to center. */
export function LensButton({
  children,
  className = "",
  type = "button",
  ...props
}: ButtonHTMLAttributes<HTMLButtonElement>) {
  return (
    <button
      {...props}
      type={type}
      className={`forme-lens ${className}`}
      onPointerMove={(e) => {
        const r = e.currentTarget.getBoundingClientRect();
        e.currentTarget.style.setProperty("--forme-lens-x", `${e.clientX - r.left}px`);
        e.currentTarget.style.setProperty("--forme-lens-y", `${e.clientY - r.top}px`);
        e.currentTarget.dataset.lit = "";
        props.onPointerMove?.(e);
      }}
      onPointerLeave={(e) => {
        delete e.currentTarget.dataset.lit;
        props.onPointerLeave?.(e);
      }}
      onFocus={(e) => {
        // Keyboard focus lights the button from its center.
        if (!e.currentTarget.matches(":hover")) {
          e.currentTarget.style.setProperty("--forme-lens-x", "50%");
          e.currentTarget.style.setProperty("--forme-lens-y", "50%");
        }
        props.onFocus?.(e);
      }}
    >
      <span className="forme-lens-light" aria-hidden="true" />
      <span className="forme-lens-label">{children}</span>
    </button>
  );
}

.forme-lens {
  --forme-lens-x: 50%;
  --forme-lens-y: 50%;
  --forme-lens-tint: #7c9cff;
  position: relative;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  align-self: center;
  box-sizing: border-box;
  height: 50px;
  padding: 0 28px;
  overflow: hidden;
  border: 0;
  border-radius: 999px;
  background: linear-gradient(180deg, #1b1b20, #0b0b0e);
  box-shadow:
    inset 0 0 0 1px #ffffff17,
    inset 0 1px 0 #ffffff12,
    inset 0 -1px 0 #00000080,
    0 12px 32px -12px #000000e6;
  color: #f4f4f5;
  font: inherit;
  font-size: 15px;
  font-weight: 500;
  letter-spacing: -0.005em;
  cursor: pointer;
  transition: transform 0.25s cubic-bezier(0.2, 0.8, 0.2, 1);
}
/* Every light layer keeps its last position and only fades, so leaving never jumps. */
.forme-lens-light,
.forme-lens::before,
.forme-lens::after {
  opacity: 0;
  transition: opacity 0.45s cubic-bezier(0.2, 0.8, 0.2, 1);
  pointer-events: none;
}
.forme-lens-light {
  position: absolute;
  inset: 0;
  z-index: -1;
  background: radial-gradient(140px circle at var(--forme-lens-x) var(--forme-lens-y), #ffffff1f, transparent 65%);
}
/* A one-pixel edge, brightest where the light sits. */
.forme-lens::before {
  content: "";
  position: absolute;
  inset: 0;
  padding: 1px;
  border-radius: inherit;
  background: radial-gradient(110px circle at var(--forme-lens-x) var(--forme-lens-y), #ffffffd9, #ffffff00 70%);
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
}
/* Colored light bleeding up through the glass from below the pointer. */
.forme-lens::after {
  content: "";
  position: absolute;
  left: var(--forme-lens-x);
  bottom: -18px;
  z-index: -1;
  width: 120px;
  height: 40px;
  border-radius: 50%;
  background: var(--forme-lens-tint);
  filter: blur(18px);
  transform: translateX(-50%);
}
.forme-lens-label {
  position: relative;
  text-shadow: 0 1px 12px #ffffff26;
}
.forme-lens[data-lit] .forme-lens-light,
.forme-lens[data-lit]::before,
.forme-lens:focus-visible .forme-lens-light,
.forme-lens:focus-visible::before {
  opacity: 1;
  transition-duration: 0.2s;
}
.forme-lens[data-lit]::after,
.forme-lens:focus-visible::after {
  opacity: 0.55;
  transition-duration: 0.2s;
}
.forme-lens:focus-visible {
  outline: 2px solid #f4f4f5;
  outline-offset: 4px;
}
.forme-lens:active {
  transform: scale(0.975);
}
.forme-lens:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
@media (prefers-reduced-motion: reduce) {
  .forme-lens,
  .forme-lens-light,
  .forme-lens::before,
  .forme-lens::after {
    transition: none;
  }
  .forme-lens:active {
    transform: none;
  }
}
